function getCurriculumByGradeAndSubject(grade, subject) {
  return CURRICULUM_TAXONOMIES.filter(c => c.gradeLevel === grade && c.subject.toLowerCase() === subject.toLowerCase());
}
function findStandardById(id) {
  return CURRICULUM_TAXONOMIES.find(c => c.standardId === id);
}

module.exports = { CURRICULUM_TAXONOMIES, getCurriculumByGradeAndSubject, findStandardById };